const isPalindrome = (inputString) => {
  const alphanumericOnly = inputString.toLowerCase().replace(/[^a-z0-9]/g, '');
  const reversedAlphanumeric = alphanumericOnly.split('').reverse().join('');
  const resultOfComparison = alphanumericOnly === reversedAlphanumeric;
  return resultOfComparison;
};

const checkIfWordIsPalindrome = (wordToCheck) => {
  const processedInput = wordToCheck.trim();
  const finalPalindromeCheck = isPalindrome(processedInput);
  return finalPalindromeCheck;
};

