const findMax = (inputArray) => {
  if (inputArray.length === 0) {
    return undefined;
  }

  let currentMaximumValue = inputArray[0];
  for (let currentElementIndex = 1; currentElementIndex < inputArray.length; currentElementIndex++) {
    const currentArrayElement = inputArray[currentElementIndex];
    if (currentArrayElement > currentMaximumValue) {
      currentMaximumValue = currentArrayElement;
    }
  }
  return currentMaximumValue;
};

