const generateFibonacci = (numberOfElements) => {
  const fibonacciSequence = [];
  let currentFirstNumber = 0;
  let currentSecondNumber = 1;

  if (numberOfElements <= 0) {
    return fibonacciSequence;
  }

  if (numberOfElements >= 1) {
    fibonacciSequence.push(currentFirstNumber);
  }

  for (let i = 1; i < numberOfElements; i++) {
    fibonacciSequence.push(currentSecondNumber);
    const nextNumberInSequence = currentFirstNumber + currentSecondNumber;
    currentFirstNumber = currentSecondNumber;
    currentSecondNumber = nextNumberInSequence;
  }

  return fibonacciSequence;
};

