const capitalizeFirstLetter = (inputString) => {
  const wordsArray = inputString.split(' ');
  const capitalizedWords = wordsArray.map((singleWord) => {
    if (singleWord.length === 0) {
      return '';
    }
    const firstCharacter = singleWord.charAt(0).toUpperCase();
    const remainingCharacters = singleWord.slice(1).toLowerCase();
    const combinedWord = firstCharacter + remainingCharacters;
    return combinedWord;
  });
  const finalResultString = capitalizedWords.join(' ');
  return finalResultString;
};

