const isPrime = (candidateNumber) => {
  if (candidateNumber < 2) {
    return false;
  }
  for (let currentDivisor = 2; currentDivisor <= Math.sqrt(candidateNumber); currentDivisor++) {
    if (candidateNumber % currentDivisor === 0) {
      return false;
    }
  }
  return true;
};

const checkIfNumberIsPrime = (inputNumber) => {
  const isCurrentlyPrime = isPrime(inputNumber);
  return isCurrentlyPrime;
};

const getPrimeStatusMessage = (testValue) => {
  const primeCheckResult = checkIfNumberIsPrime(testValue);
  if (primeCheckResult) {
    return `${testValue} is a prime number.`;
  } else {
    return `${testValue} is not a prime number.`;
  }
};

const primeNumberExample = 17;
const anotherNumberToCheck = 15;
const finalResultForPrimeExample = getPrimeStatusMessage(primeNumberExample);
const finalResultForCompositeExample = getPrimeStatusMessage(anotherNumberToCheck);

