function parseUrlParams(urlString) {
  const urlAnchorElement = document.createElement('a');
  urlAnchorElement.href = urlString;
  const queryString = urlAnchorElement.search.substring(1);
  const parameterObject = {};

  if (queryString.length === 0) {
    return parameterObject;
  }

  const parameterPairs = queryString.split('&');

  for (let i = 0; i < parameterPairs.length; i++) {
    const singlePair = parameterPairs[i];
    const indexOfEquals = singlePair.indexOf('=');
    if (indexOfEquals === -1) {
      continue;
    }
    const parameterKey = decodeURIComponent(singlePair.substring(0, indexOfEquals));
    const parameterValue = decodeURIComponent(singlePair.substring(indexOfEquals + 1));
    parameterObject[parameterKey] = parameterValue;
  }

  return parameterObject;
}

