function rollDice(numberOfSides) {
  const minPossibleValue = 1;
  const maxPossibleValue = Math.floor(numberOfSides);
  const randomNumberGenerator = Math.random();
  const scaledRandomNumber = randomNumberGenerator * maxPossibleValue;
  const rawDiceRollResult = Math.floor(scaledRandomNumber) + minPossibleValue;
  return rawDiceRollResult;
}

