const calculateMedian = (inputArrayOfNumbers) => {
  const sortedNumericData = [...inputArrayOfNumbers].sort((a, b) => a - b);
  const totalNumberOfElements = sortedNumericData.length;

  if (totalNumberOfElements === 0) {
    return 0;
  }

  const isEvenLength = totalNumberOfElements % 2 === 0;

  if (isEvenLength) {
    const firstMiddleIndex = totalNumberOfElements / 2 - 1;
    const secondMiddleIndex = totalNumberOfElements / 2;
    const firstMiddleNumber = sortedNumericData[firstMiddleIndex];
    const secondMiddleNumber = sortedNumericData[secondMiddleIndex];
    const averageOfMiddleNumbers = (firstMiddleNumber + secondMiddleNumber) / 2;
    return averageOfMiddleNumbers;
  } else {
    const exactMiddleIndex = Math.floor(totalNumberOfElements / 2);
    const middleNumberValue = sortedNumericData[exactMiddleIndex];
    return middleNumberValue;
  }
};

