  const final_date = new Date(second_date_string);

  const initial_date_time = initial_date.getTime();
  const final_date_time = final_date.getTime();

  const time_difference_in_milliseconds = Math.abs(final_date_time - initial_date_time);
  const calculated_days_difference = Math.round(time_difference_in_milliseconds / milliseconds_per_day);

  return calculated_days_difference;
}

