const formatCurrency = (inputAmount, currencySymbol) => {
  const fixedTwoDecimals = inputAmount.toFixed(2);
  const parts = fixedTwoDecimals.split('.');
  const integerPart = parts[0];
  const decimalPart = parts[1];

