    return '';
  }

  const fileNameBeforeDot = fullFileName.substring(minimumValidIndex, lastDotIndex);
  const secondLastDotIndex = fileNameBeforeDot.lastIndexOf('.');

  if (fullFileName.startsWith('.')) {
    return '';
  }

  if (secondLastDotIndex !== -1 && fullFileName.slice(lastDotIndex + 1).includes('.')) {
