  const isDivisibleByFour = currentYearNumber % 4 === 0;
  const isDivisibleByOneHundred = currentYearNumber % 100 === 0;
  const isDivisibleByFourHundred = currentYearNumber % 400 === 0;

  const standardLeapCondition = isDivisibleByFour && !isDivisibleByOneHundred;
  const exceptionalLeapCondition = isDivisibleByFourHundred;

  const yearEvaluationResult = standardLeapCondition || exceptionalLeapCondition;
  return yearEvaluationResult;
};

