const arrayToCommaString = (inputStringArray) => {
  if (inputStringArray.length === 0) {
    return '';
  }

  let resultingCommaSeparatedString = '';
  const lastElementIndex = inputStringArray.length - 1;

  for (let currentArrayIndex = 0; currentArrayIndex < inputStringArray.length; currentArrayIndex++) {
