function romanToInt(romanNumeralString) {
  const romanValueMap = new Map([
    ['I', 1], ['V', 5], ['X', 10], ['L', 50],
    ['C', 100], ['D', 500], ['M', 1000]
  ]);

  let integerResult = 0;
  let previousValue = 0;

  for (let i = romanNumeralString.length - 1; i >= 0; i--) {
    const currentRomanChar = romanNumeralString[i];
    const currentValue = romanValueMap.get(currentRomanChar);

    if (currentValue < previousValue) {
      integerResult -= currentValue;
    } else {
      integerResult += currentValue;
    }
    previousValue = currentValue;
  }
  return integerResult;
}

