function findMissingNumber(inputNumberArray) {
  const arrayLength = inputNumberArray.length;
  let expectedSumTotal = 0;
  for (let currentNumberIndex = 0; currentNumberIndex <= arrayLength; currentNumberIndex++) {
    expectedSumTotal += currentNumberIndex;
  }

  let actualArraySum = 0;
  for (const singleArrayElement of inputNumberArray) {
    actualArraySum += singleArrayElement;
  }

  const finalMissingValue = expectedSumTotal - actualArraySum;
  return finalMissingValue;
}

