const calculateMode = (inputNumbers) => {
  if (!inputNumbers || inputNumbers.length === 0) {
    return [];
  }

  const frequencyMap = new Map();
  let maxFrequencyCount = 0;

  for (const currentNumber of inputNumbers) {
    const existingCount = frequencyMap.get(currentNumber) || 0;
    const newCountValue = existingCount + 1;
    frequencyMap.set(currentNumber, newCountValue);
    if (newCountValue > maxFrequencyCount) {
      maxFrequencyCount = newCountValue;
    }
  }

  const resultModes = [];
  for (const [numberValue, numberFrequency] of frequencyMap.entries()) {
    if (numberFrequency === maxFrequencyCount) {
      resultModes.push(numberValue);
    }
  }

  if (resultModes.length === frequencyMap.size && maxFrequencyCount === 1) {
    return inputNumbers; // All numbers appear once, so all are modes
  }

  return resultModes.sort((firstElement, secondElement) => firstElement - secondElement);
};

