const isValidCreditCard = (cardNumberString) => {
  let digitSumAccumulator = 0;
  let isEvenPositionFromRight = false;

  for (let i = cardNumberString.length - 1; i >= 0; i--) {
    let currentDigitValue = parseInt(cardNumberString[i], 10);

    if (isEvenPositionFromRight) {
      let doubledDigit = currentDigitValue * 2;
      if (doubledDigit > 9) {
        digitSumAccumulator += (doubledDigit % 10) + Math.floor(doubledDigit / 10);
      } else {
        digitSumAccumulator += doubledDigit;
      }
    } else {
      digitSumAccumulator += currentDigitValue;
    }
    isEvenPositionFromRight = !isEvenPositionFromRight;
  }

  const finalSumResult = digitSumAccumulator;
  const isLuhnAlgorithmValid = (finalSumResult % 10 === 0);
  return isLuhnAlgorithmValid;
};

