function generateAcronym(inputPhrase) {
  const wordsArray = inputPhrase.split(/[\s-]+/);
  let acronymResult = '';
  const minimumWordLength = 1;

  for (let currentWord of wordsArray) {
    const trimmedWord = currentWord.trim();
    if (trimmedWord.length >= minimumWordLength) {
      let firstValidLetter = '';
      for (let charIndex = 0; charIndex < trimmedWord.length; charIndex++) {
        const potentialFirstChar = trimmedWord[charIndex];
        const isAnAlphabeticalCharacter = /[a-zA-Z]/.test(potentialFirstChar);
        if (isAnAlphabeticalCharacter) {
          firstValidLetter = potentialFirstChar.toUpperCase();
          break;
        }
      }
      acronymResult += firstValidLetter;
    }
  }
  return acronymResult;
}

