const caesarCipher = (inputText, shiftAmount) => {
  let encryptedMessage = '';
  const effectiveShift = shiftAmount % 26;

  for (let charIndex = 0; charIndex < inputText.length; charIndex++) {
    const currentCharacter = inputText[charIndex];
    const characterCode = currentCharacter.charCodeAt(0);

    if (characterCode >= 65 && characterCode <= 90) { // Uppercase letters
      const shiftedCode = ((characterCode - 65 + effectiveShift + 26) % 26) + 65;
      encryptedMessage += String.fromCharCode(shiftedCode);
    } else if (characterCode >= 97 && characterCode <= 122) { // Lowercase letters
      const shiftedCode = ((characterCode - 97 + effectiveShift + 26) % 26) + 97;
      encryptedMessage += String.fromCharCode(shiftedCode);
    } else {
      encryptedMessage += currentCharacter; // Non-alphabetic characters remain unchanged
    }
  }
  return encryptedMessage;
};

