const isValidParentheses = (inputString) => {
  const bracketStack = [];
  const bracketMap = {
    '(': ')',
    '{': '}',
    '[': ']',
  };

  for (let characterIndex = 0; characterIndex < inputString.length; characterIndex++) {
    const currentCharacter = inputString[characterIndex];
    if (bracketMap[currentCharacter]) {
      bracketStack.push(currentCharacter);
    } else {
      if (bracketStack.length === 0) {
        return false;
      }
      const lastOpenBracket = bracketStack.pop();
      if (bracketMap[lastOpenBracket] !== currentCharacter) {
        return false;
      }
    }
  }

  const hasUnclosedBrackets = bracketStack.length === 0;
  return hasUnclosedBrackets;
};

