function hasEventCollisions(allScheduledEvents) {
  const eventCount = allScheduledEvents.length;
  if (eventCount <= 1) {
    return false;
  }

  const sortedEventsByStartTime = [...allScheduledEvents].sort((firstEvent, secondEvent) => {
    return firstEvent.start - secondEvent.start;
  });

  for (let currentEventIndex = 0; currentEventIndex < eventCount - 1; currentEventIndex++) {
    const currentCalendarEvent = sortedEventsByStartTime[currentEventIndex];
    const nextCalendarEvent = sortedEventsByStartTime[currentEventIndex + 1];

    const currentEventEndTime = currentCalendarEvent.end;
    const nextEventStartTime = nextCalendarEvent.start;

    if (currentEventEndTime > nextEventStartTime) {
      return true; // Found an overlapping occurrence
    }
  }
  return false; // No scheduling conflicts detected
}

