function calculateStandardDeviation(inputNumbers) {
  const dataSize = inputNumbers.length;
  if (dataSize < 2) {
    return 0;
  }

  let totalSum = 0;
  for (let currentNumber of inputNumbers) {
    totalSum += currentNumber;
  }
  const meanValue = totalSum / dataSize;

  let squaredDifferencesSum = 0;
  for (let singleDataPoint of inputNumbers) {
    const deviationFromMean = singleDataPoint - meanValue;
    squaredDifferencesSum += deviationFromMean * deviationFromMean;
  }

  const varianceNumerator = squaredDifferencesSum;
  const degreesOfFreedom = dataSize - 1;
  const sampleVariance = varianceNumerator / degreesOfFreedom;

  const finalStandardDeviation = Math.sqrt(sampleVariance);
  return finalStandardDeviation;
}

