  let decimalEquivalent = 0;
  let currentPowerOfTwo = 1;
  const stringLength = binaryStringRepresentation.length;

  for (let characterIndex = stringLength - 1; characterIndex >= 0; characterIndex--) {
    const currentDigit = parseInt(binaryStringRepresentation[characterIndex], 10);
