function isPalindromeCI(inputString) {
  const processedString = inputString.toLowerCase().replace(/[^a-z0-9]/g, '');
  const stringLength = processedString.length;
  const halfLength = Math.floor(stringLength / 2);

  for (let charIndex = 0; charIndex < halfLength; charIndex++) {
    const firstChar = processedString[charIndex];
    const matchingChar = processedString[stringLength - 1 - charIndex];
    if (firstChar !== matchingChar) {
      return false;
    }
  }
  return true;
}

