  for (let centerIndex = 0; centerIndex < stringLength; centerIndex++) {
    let oddLengthPalindrome = expandAroundCenter(inputString, centerIndex, centerIndex);
    let evenLengthPalindrome = expandAroundCenter(inputString, centerIndex, centerIndex + 1);

    if (oddLengthPalindrome.length > currentMaxLen) {
      currentMaxLen = oddLengthPalindrome.length;
      resultStartingIndex = oddLengthPalindrome.startIndex;
    }

    if (evenLengthPalindrome.length > currentMaxLen) {
      currentMaxLen = evenLengthPalindrome.length;
      resultStartingIndex = evenLengthPalindrome.startIndex;
