function expandAroundCenter(fullString, leftPointer, rightPointer) {
  let initialLeft = leftPointer;
  let initialRight = rightPointer;

  while (initialLeft >= 0 && initialRight < fullString.length && fullString.charAt(initialLeft) === fullString.charAt(initialRight)) {
    initialLeft--;
    initialRight++;
