  }

  push(itemToAdd) {
    this.stackElements.push(itemToAdd);
    this.currentStackSize++;
  }

  pop() {
    if (this.currentStackSize === 0) {
      return null;
    }
    this.currentStackSize--;
    const poppedValue = this.stackElements.pop();
    return poppedValue;
