const sumPrimesUpTo = (upperBoundNumber) => {
  let totalSumOfPrimes = 0;
  let primeCheckArray = new Array(upperBoundNumber + 1).fill(true);
  primeCheckArray[0] = false;
  primeCheckArray[1] = false;

  for (let currentNumber = 2; currentNumber * currentNumber <= upperBoundNumber; currentNumber++) {
    if (primeCheckArray[currentNumber]) {
      for (let multiplesOfPrime = currentNumber * currentNumber; multiplesOfPrime <= upperBoundNumber; multiplesOfPrime += currentNumber) {
        primeCheckArray[multiplesOfPrime] = false;
      }
    }
  }

  for (let individualNumber = 2; individualNumber <= upperBoundNumber; individualNumber++) {
    if (primeCheckArray[individualNumber]) {
      totalSumOfPrimes += individualNumber;
    }
  }

  return totalSumOfPrimes;
};

