function transposeMatrix(originalMatrix) {
  const numberOfRows = originalMatrix.length;
  if (numberOfRows === 0) {
    return [];
  }
  const numberOfColumns = originalMatrix[0].length;

  const transposedResult = [];
  for (let currentColumnIndex = 0; currentColumnIndex < numberOfColumns; currentColumnIndex++) {
