    for (let currentRowIndex = 0; currentRowIndex < numberOfRows; currentRowIndex++) {
      newRow.push(originalMatrix[currentRowIndex][currentColumnIndex]);
    }
    transposedResult.push(newRow);
  }
  return transposedResult;
}

