const calculateSemiPerimeter = (firstSideLength, secondSideLength, thirdSideLength) => {
  return (firstSideLength + secondSideLength + thirdSideLength) / 2;
};

const triangleAreaHeron = (sideA, sideB, sideC) => {
  const semiPerimeter = calculateSemiPerimeter(sideA, sideB, sideC);
  const areaValueSquared = semiPerimeter *
                           (semiPerimeter - sideA) *
                           (semiPerimeter - sideB) *
                           (semiPerimeter - sideC);
  const finalCalculatedArea = Math.sqrt(areaValueSquared);
  return finalCalculatedArea;
};

