function countInversions(inputArray) {
    let inversionCount = 0;

    function mergeSortAndCount(currentArray) {
        if (currentArray.length <= 1) {
            return currentArray;
        }

        const midPoint = Math.floor(currentArray.length / 2);
        const leftHalf = currentArray.slice(0, midPoint);
        const rightHalf = currentArray.slice(midPoint);

        const sortedLeft = mergeSortAndCount(leftHalf);
        const sortedRight = mergeSortAndCount(rightHalf);

        let mergedResult = [];
        let leftIndex = 0;
        let rightIndex = 0;

        while (leftIndex < sortedLeft.length && rightIndex < sortedRight.length) {
            if (sortedLeft[leftIndex] <= sortedRight[rightIndex]) {
                mergedResult.push(sortedLeft[leftIndex]);
                leftIndex++;
            } else {
                mergedResult.push(sortedRight[rightIndex]);
                inversionCount += (sortedLeft.length - leftIndex);
                rightIndex++;
            }
        }

        while (leftIndex < sortedLeft.length) {
            mergedResult.push(sortedLeft[leftIndex]);
            leftIndex++;
        }

        while (rightIndex < sortedRight.length) {
            mergedResult.push(sortedRight[rightIndex]);
            rightIndex++;
        }
        return mergedResult;
    }

    mergeSortAndCount(inputArray);
    return inversionCount;
}

