const parseLogEntry = (rawLogLine) => {
  const openingBracketIndex = rawLogLine.indexOf('[');
  const closingBracketIndex = rawLogLine.indexOf(']');

  if (openingBracketIndex !== 0 || closingBracketIndex === -1) {
    throw new Error('Invalid log line format: missing or misplaced brackets');
  }

  const logTimestampString = rawLogLine.substring(openingBracketIndex + 1, closingBracketIndex);
  const fullLogMessage = rawLogLine.substring(closingBracketIndex + 1).trim();

  const createLogObject = (timeValue, entryMessage) => ({
    timestamp: timeValue,
    message: entryMessage,
  });

  return createLogObject(logTimestampString, fullLogMessage);
};

