const isValidISBN10 = (rawIsbnString) => {
  const normalizedIsbn = rawIsbnString.replace(/[-]/g, '');
  const requiredLength = 10;

  if (normalizedIsbn.length !== requiredLength) {
    return false;
  }

  let runningTotalSum = 0;
  const maximumMultiplier = 10;

  for (let characterIndex = 0; characterIndex < requiredLength; characterIndex++) {
    const currentCharacter = normalizedIsbn[characterIndex];
    let digitValue;

    if (currentCharacter === 'X' && characterIndex === requiredLength - 1) {
      digitValue = maximumMultiplier;
    } else if (/\d/.test(currentCharacter)) {
      digitValue = parseInt(currentCharacter, 10);
    } else {
      return false; // Non-digit, non-X character found
    }

    const currentMultiplier = maximumMultiplier - characterIndex;
    runningTotalSum += digitValue * currentMultiplier;
  }

  const isSumDivisibleByEleven = runningTotalSum % 11 === 0;
  return isSumDivisibleByEleven;
};

