const getQuadrant = (xCoordinate, yCoordinate) => {
  const isXCoordinateZero = xCoordinate === 0;
  const isYCoordinateZero = yCoordinate === 0;

  if (isXCoordinateZero || isYCoordinateZero) {
    return 0; // Point is on an axis or at the origin
  }

  const isPositiveXValue = xCoordinate > 0;
  const isPositiveYValue = yCoordinate > 0;

  if (isPositiveXValue && isPositiveYValue) {
    return 1; // First quadrant
  } else if (!isPositiveXValue && isPositiveYValue) {
    return 2; // Second quadrant
  } else if (!isPositiveXValue && !isPositiveYValue) {
    return 3; // Third quadrant
  } else {
    return 4; // Fourth quadrant
  }
};

