const isPalindromeNumber = (inputNumber) => {
  const numberAsString = String(inputNumber);
  const stringLength = numberAsString.length;
  const lastIndexPosition = stringLength - 1;

  for (let currentIterationIndex = 0; currentIterationIndex < stringLength / 2; currentIterationIndex++) {
    const charFromFront = numberAsString[currentIterationIndex];
    const charFromBack = numberAsString[lastIndexPosition - currentIterationIndex];
    if (charFromFront !== charFromBack) {
      return false;
    }
  }
  return true;
};

