const parseTime = (timeString) => {
  const [hourPart, minutePart] = timeString.split(':').map(Number);
  return hourPart * 60 + minutePart;
};

const hasConflict = (existingEvent, newEvent) => {
  const existingEventStartTime = parseTime(existingEvent.start);
  const existingEventEndTime = parseTime(existingEvent.end);
  const newEventStartTime = parseTime(newEvent.start);
  const newEventEndTime = parseTime(newEvent.end);

  const newEventStartsBeforeExistingEventEnds = newEventStartTime < existingEventEndTime;
  const newEventEndsAfterExistingEventStarts = newEventEndTime > existingEventStartTime;

  return newEventStartsBeforeExistingEventEnds && newEventEndsAfterExistingEventStarts;
};

