const calculateWeightedAverage = (inputDataArray) => {
  let totalWeightedSum = 0;
  let totalWeightSum = 0;

  for (const dataItem of inputDataArray) {
    const itemValue = dataItem.value;
    const itemWeight = dataItem.weight;
    totalWeightedSum += itemValue * itemWeight;
    totalWeightSum += itemWeight;
  }

  if (totalWeightSum === 0) {
    return 0;
  }

  const finalWeightedAverage = totalWeightedSum / totalWeightSum;
  return finalWeightedAverage;
};

