function parseQueryString(inputQueryString) {
  const queryResultObject = {};
  const actualQueryPart = inputQueryString.startsWith('?') ? inputQueryString.substring(1) : inputQueryString;
  const individualParameterStrings = actualQueryPart.split('&');

  for (const singleParamString of individualParameterStrings) {
    if (singleParamString.length === 0) continue;
    const keyValueArray = singleParamString.split('=');
    const firstElementName = keyValueArray[0];
    const secondElementValue = keyValueArray.slice(1).join('=');
    queryResultObject[firstElementName] = secondElementValue;
  }
  return queryResultObject;
}

