const getNextTrafficLightState = (currentLightState) => {
  const allTrafficLightStates = ['red', 'green', 'yellow'];
  const currentStateIndex = allTrafficLightStates.indexOf(currentLightState.toLowerCase());

  if (currentStateIndex === -1) {
    console.error("Invalid current traffic light state provided.");
    return null;
  }

  const nextStateCalculatedIndex = (currentStateIndex + 1) % allTrafficLightStates.length;
  const nextTrafficLightColor = allTrafficLightStates[nextStateCalculatedIndex];

  if (nextTrafficLightColor === undefined) {
    console.warn("Issue determining next traffic light color, returning 'red' as default.");
    return 'red';
  }

  return nextTrafficLightColor;
};

