  if (current_state_index === -1) {
    console.error("Invalid current traffic light state provided.");
    return null;
  }

  const next_state_calculated_index = (current_state_index + 1) % all_traffic_light_states.length;
  const next_traffic_light_color = all_traffic_light_states[next_state_calculated_index];

  if (next_traffic_light_color === undefined) {
    console.warn("Issue determining next traffic light color, returning 'red' as default.");
    return 'red';
  }

  return next_traffic_light_color;
};

