  let previousCharacterCode = inputLetterSequence[0].charCodeAt(0) - 1;

  for (let currentLetterIndex = 0; currentLetterIndex < inputLetterSequence.length; currentLetterIndex++) {
    const currentCharacterCode = inputLetterSequence[currentLetterIndex].charCodeAt(0);
    const expectedNextCharacterCode = previousCharacterCode + 1;

    if (currentCharacterCode !== expectedNextCharacterCode) {
      return String.fromCharCode(expectedNextCharacterCode);
