function getDaysInMonth(currentYear, oneIndexedMonth) {
  const monthDaysCount = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  let actualMonthIndex = oneIndexedMonth - 1;

  if (actualMonthIndex === 1 && checkIfLeapYear(currentYear)) {
    return 29;
  }
  return monthDaysCount[actualMonthIndex];
}

function checkIfLeapYear(yearToExamine) {
  const isDivisibleByFour = yearToExamine % 4 === 0;
  const isDivisibleByHundred = yearToExamine % 100 === 0;
  const isDivisibleByFourHundred = yearToExamine % 400 === 0;

  return (isDivisibleByFour && !isDivisibleByHundred) || isDivisibleByFourHundred;
}

