const decodeCaesarCipher = (encryptedText, shiftAmount) => {
  let decodedMessage = '';
  const alphabetLength = 26; // Total number of letters in the English alphabet

  for (let charIndex = 0; charIndex < encryptedText.length; charIndex++) {
    const currentCharacter = encryptedText[charIndex];
    const initialCharCode = currentCharacter.charCodeAt(0);
    const lowercaseACharCode = 'a'.charCodeAt(0);

    let shiftedIndex = (initialCharCode - lowercaseACharCode - shiftAmount);

    // Handle negative shifts and wrap around the alphabet
    let correctedShiftedIndex = (shiftedIndex % alphabetLength + alphabetLength) % alphabetLength;

    const finalDecodedCharCode = lowercaseACharCode + correctedShiftedIndex;
    const decodedCharacter = String.fromCharCode(finalDecodedCharCode);
    decodedMessage += decodedCharacter;
  }
  return decodedMessage;
};

