const formatSecondsToHMS = (totalSecondsInput) => {
  const SECONDS_IN_AN_HOUR = 3600;
  const SECONDS_IN_A_MINUTE = 60;

  const totalHours = Math.floor(totalSecondsInput / SECONDS_IN_AN_HOUR);
  const remainingSecondsAfterHours = totalSecondsInput % SECONDS_IN_AN_HOUR;
  const totalMinutes = Math.floor(remainingSecondsAfterHours / SECONDS_IN_A_MINUTE);
  const finalSeconds = remainingSecondsAfterHours % SECONDS_IN_A_MINUTE;

  const padNumberWithZero = (numberToPad) => String(numberToPad).padStart(2, '0');

  const paddedHours = padNumberWithZero(totalHours);
  const paddedMinutes = padNumberWithZero(totalMinutes);
  const paddedSeconds = padNumberWithZero(finalSeconds);

  const formattedTimeString = `${paddedHours}:${paddedMinutes}:${paddedSeconds}`;
  return formattedTimeString;
};

