const findLongestCommonSuffix = (stringCollection) => {
  if (stringCollection.length === 0) {
    return "";
  }
  let shortestStringLength = Number.MAX_SAFE_INTEGER;
  for (const currentString of stringCollection) {
    shortestStringLength = Math.min(shortestStringLength, currentString.length);
  }

  let longestCommonPart = "";
  for (let suffixLength = 1; suffixLength <= shortestStringLength; suffixLength++) {
    const candidateSuffix = stringCollection[0].slice(-suffixLength);
    let allStringsMatch = true;
    for (let currentStringIndex = 1; currentStringIndex < stringCollection.length; currentStringIndex++) {
      if (!stringCollection[currentStringIndex].endsWith(candidateSuffix)) {
        allStringsMatch = false;
        break;
      }
    }
    if (allStringsMatch) {
      longestCommonPart = candidateSuffix;
    } else {
      break;
    }
  }
  return longestCommonPart;
};

