const getRandomInt = (minimumValue, maximumValue) => {
  const minCeiled = Math.ceil(minimumValue);
  const maxFloored = Math.floor(maximumValue);
  const randomNumber = Math.random();
  const rangeSpan = maxFloored - minCeiled + 1;
  const scaledRandomNumber = randomNumber * rangeSpan;
  const finalResult = Math.floor(scaledRandomNumber) + minCeiled;
  return finalResult;
};

