const getOverlappingEvents = (incomingEvent, currentEventList) => {
  const convertTimeToMinutes = (timeStringValue) => {
    const [hoursValue, minutesValue] = timeStringValue.split(':').map(Number);
    return hoursValue * 60 + minutesValue;
  };

  const newEventStartTimeInMinutes = convertTimeToMinutes(incomingEvent.start);
  const newEventEndTimeInMinutes = convertTimeToMinutes(incomingEvent.end);

  const determineOverlapStatus = (existingEventSchedule) => {
    const existingEventStartTimeInMinutes = convertTimeToMinutes(existingEventSchedule.start);
    const existingEventEndTimeInMinutes = convertTimeToMinutes(existingEventSchedule.end);

    const hasTimeConflict =
      (newEventStartTimeInMinutes < existingEventEndTimeInMinutes && newEventEndTimeInMinutes > existingEventStartTimeInMinutes);

    return hasTimeConflict;
  };

  const filteredOverlappingEvents = currentEventList.filter(determineOverlapStatus);

  return filteredOverlappingEvents;
};

