function containsSubarray(mainArray, subArray) {
  const mainArrayLength = mainArray.length;
  const subArrayLength = subArray.length;

  if (subArrayLength === 0) {
    return true;
  }
  if (subArrayLength > mainArrayLength) {
    return false;
  }

  for (let currentMainIndex = 0; currentMainIndex <= mainArrayLength - subArrayLength; currentMainIndex++) {
    let allElementsMatch = true;
    for (let currentSubIndex = 0; currentSubIndex < subArrayLength; currentSubIndex++) {
      if (mainArray[currentMainIndex + currentSubIndex] !== subArray[currentSubIndex]) {
        allElementsMatch = false;
        break;
      }
    }
    if (allElementsMatch) {
      return true;
    }
  }
  return false;
}

