const getElapsedTimeInMinutes = (firstTimeString, secondTimeString) => {
  const parseTime = (timeStringValue) => {
    const timeParts = timeStringValue.split(':');
    const hoursPart = parseInt(timeParts[0], 10);
    const minutesPart = parseInt(timeParts[1], 10);
    return { hoursPart, minutesPart };
  };

  const startParsedTime = parseTime(firstTimeString);
  const endParsedTime = parseTime(secondTimeString);

  const startTotalMinutes = (startParsedTime.hoursPart * 60) + startParsedTime.minutesPart;
  const endTotalMinutes = (endParsedTime.hoursPart * 60) + endParsedTime.minutesPart;

  const totalTimeDifferenceInMinutes = endTotalMinutes - startTotalMinutes;
  return totalTimeDifferenceInMinutes;
};

