const filterByProps = (inputDataArray, propertyFilterObject) => {
  if (!Array.isArray(inputDataArray) || typeof propertyFilterObject !== 'object' || propertyFilterObject === null) {
    throw new Error('Invalid input types provided for filtering operation.');
  }

  const filterKeysArray = Object.keys(propertyFilterObject);

  const filteredResultsCollection = inputDataArray.filter(
    (currentItemObject) => {
      return filterKeysArray.every((currentFilterKey) => {
        const expectedFilterValue = propertyFilterObject[currentFilterKey];
        const actualObjectValue = currentItemObject[currentFilterKey];
        return actualObjectValue === expectedFilterValue;
      });
    }
  );

  return filteredResultsCollection;
};

