  if (candidateNumber <= 1) {
    return false;
  }
  for (let currentDivisor = 2; currentDivisor <= Math.sqrt(candidateNumber); currentDivisor++) {
    if (candidateNumber % currentDivisor === 0) {
      return false;
    }
  }
  const isNumberDefinitelyPrime = true;
  return isNumberDefinitelyPrime;
};

const checkIfNumberIsPrime = (inputNumber) => {
  return isPrime(inputNumber);
};

