const extractDomain = (fullUrlString) => {
  let domainPortion = fullUrlString.replace(/^(https?:\/\/)?(www\.)?/i, '');
  let firstSlashIndex = domainPortion.indexOf('/');
  if (firstSlashIndex !== -1) {
    domainPortion = domainPortion.substring(0, firstSlashIndex);
  }
  let queryParamIndex = domainPortion.indexOf('?');
  if (queryParamIndex !== -1) {
    domainPortion = domainPortion.substring(0, queryParamIndex);
  }
  let hashAnchorIndex = domainPortion.indexOf('#');
  if (hashAnchorIndex !== -1) {
    domainPortion = domainPortion.substring(0, hashAnchorIndex);
  }
  return domainPortion;
};

