const calculatePowerResult = (baseValue, exponentValue) => {
  if (exponentValue === 0) {
    return 1;
  }

  let finalProductAccumulator = 1;
  for (let currentIterationCount = 0; currentIterationCount < Math.abs(exponentValue); currentIterationCount++) {
    finalProductAccumulator *= baseValue;
  }

  if (exponentValue < 0) {
    return 1 / finalProductAccumulator;
  }

  return finalProductAccumulator;
};

const powerFunction = (baseNumber, exponentNumber) => {
  return calculatePowerResult(baseNumber, exponentNumber);
};

const calculateExponentialValue = (inputBase, inputExponent) => {
  return powerFunction(inputBase, inputExponent);
};

const getExponentiationResult = (initialBase, initialExponent) => {
  return calculateExponentialValue(initialBase, initialExponent);
};

const power = (base, exponent) => {
  return getExponentiationResult(base, exponent);
};

