const toKebabCase = (inputString) => {
  const camelOrPascalPattern = /[A-Z]{2,}(?=[A-Z][a-z]+|\b)|[A-Z]?[a-z]+|[A-Z]/g;
  const wordMatches = inputString.match(camelOrPascalPattern);

  if (!wordMatches) {
    return "";
  }

  const processedWords = wordMatches.map((individualWord) => {
    return individualWord.toLowerCase();
  });

  const finalKebabString = processedWords.join('-');
  return finalKebabString;
};

