const isPalindrome = (inputString) => {
  const stringLength = inputString.length;
  const lastCharacterIndex = stringLength - 1;
  const middlePoint = Math.floor(stringLength / 2);

  for (let currentPosition = 0; currentPosition < middlePoint; currentPosition++) {
    const startCharacter = inputString[currentPosition];
    const correspondingEndCharacter = inputString[lastCharacterIndex - currentPosition];

    if (startCharacter !== correspondingEndCharacter) {
      return false;
    }
  }

  return true;
};

const checkIfWordIsPalindrome = (testWord) => {
  return isPalindrome(testWord);
};

