const truncateString = (inputString, maximumLength) => {
  if (inputString.length <= maximumLength) {
    return inputString;
  }

  const ellipsisCharacters = '...';
  const effectiveMaxLength = maximumLength - ellipsisCharacters.length;

  if (effectiveMaxLength < 0) {
    return ellipsisCharacters;
  }

  const truncatedPart = inputString.substring(0, effectiveMaxLength);
  const finalTruncatedString = truncatedPart + ellipsisCharacters;
  return finalTruncatedString;
};

const exampleOneResult = truncateString('hello world', 7);
const anotherExampleResult = truncateString('short', 10);
const edgeCaseTest = truncateString('very long string', 3);
const zeroLengthTest = truncateString('test', 0);
const exactLengthTest = truncateString('exactly', 7);

