const countWords = (inputStringValue) => {
  if (inputStringValue === null || inputStringValue.trim() === "") {
    return 0;
  }
  const trimmedString = inputStringValue.trim();
  const stringSplitBySpaces = trimmedString.split(' ');
  let wordCountAccumulator = 0;

  for (let currentWordCandidate of stringSplitBySpaces) {
    const cleanedWordForCounting = currentWordCandidate.trim();
    if (cleanedWordForCounting.length > 0) {
      wordCountAccumulator++;
    }
  }
  return wordCountAccumulator;
};

