const mergeAlternately = (firstInputArray, secondInputArray) => {
  const mergedResultContainer = [];
  let currentIndexFirst = 0;
  let currentIndexSecond = 0;
  const maxLength = Math.max(firstInputArray.length, secondInputArray.length);

  while (currentIndexFirst < maxLength || currentIndexSecond < maxLength) {
    if (currentIndexFirst < firstInputArray.length) {
      mergedResultContainer.push(firstInputArray[currentIndexFirst]);
    }
    if (currentIndexSecond < secondInputArray.length) {
      mergedResultContainer.push(secondInputArray[currentIndexSecond]);
    }
    currentIndexFirst++;
    currentIndexSecond++;
  }

  return mergedResultContainer;
};

