const endsWith = (mainString, searchSuffix) => {
  if (typeof mainString !== 'string' || typeof searchSuffix !== 'string') {
    return false;
  }
  const mainStringLength = mainString.length;
  const suffixLength = searchSuffix.length;

  if (suffixLength > mainStringLength) {
    return false;
  }

  const startIndex = mainStringLength - suffixLength;
  const extractedEnding = mainString.substring(startIndex);

  const areStringsEqual = extractedEnding === searchSuffix;
  return areStringsEqual;
};

