  const suffix_length = search_suffix.length;

  if (suffix_length > main_string_length) {
    return false;
  }

  const start_index = main_string_length - suffix_length;
  const extracted_ending = main_string.substring(start_index);

  const are_strings_equal = extracted_ending === search_suffix;
  return are_strings_equal;
};

