  const minResultValue = 1;
  const maxResultValue = 6;
  const rangeOfPossibleOutcomes = maxResultValue - minResultValue + 1;
  const rawRandomNumber = Math.random();
  const scaledRandomNumber = rawRandomNumber * rangeOfPossibleOutcomes;
  const floorScaledNumber = Math.floor(scaledRandomNumber);
  const finalCalculatedValue = floorScaledNumber + minResultValue;
  return finalCalculatedValue;
}

