function convertStringToTitleCase(inputString) {
  const wordsArray = inputString.toLowerCase().split(' ');
  const capitalizedWords = wordsArray.map((singleWord) => {
    if (singleWord.length === 0) {
      return '';
    }
    const firstLetter = singleWord.charAt(0).toUpperCase();
    const remainingLetters = singleWord.slice(1);
    const finalTransformedWord = firstLetter + remainingLetters;
    return finalTransformedWord;
  });
  const finalTitleCasedString = capitalizedWords.join(' ');
  return finalTitleCasedString;
}

