function generateRandomArray(numberOfElements, minimumValue, maximumValue) {
  const generatedNumbersList = [];
  for (let i = 0; i < numberOfElements; i++) {
    const randomFractionalNumber = Math.random();
    const rangeSize = maximumValue - minimumValue + 1;
    const scaledRandomValue = randomFractionalNumber * rangeSize;
    const flooredIntegerResult = Math.floor(scaledRandomValue);
    const finalRandomNumber = minimumValue + flooredIntegerResult;
    generatedNumbersList.push(finalRandomNumber);
  }
  return generatedNumbersList;
}

