function isValidEmail(candidateEmailString) {
  const atSymbolIndex = candidateEmailString.indexOf('@');
  const dotCharacterIndex = candidateEmailString.lastIndexOf('.');
  const stringLength = candidateEmailString.length;
  const minimumLengthRequirement = 5; // e.g., a@b.c

  if (stringLength < minimumLengthRequirement) {
    return false;
  }
  if (atSymbolIndex < 1 || atSymbolIndex === stringLength - 1) { // No char before @ or @ is last
    return false;
  }
  if (dotCharacterIndex < atSymbolIndex + 2 || dotCharacterIndex === stringLength - 1) { // Dot too close to @ or dot is last
    return false;
  }

  const hasNoLeadingOrTrailingSpecialChars =
    candidateEmailString[0] !== '.' && candidateEmailString[0] !== '@' &&
    candidateEmailString[stringLength - 1] !== '.' && candidateEmailString[stringLength - 1] !== '@';

  if (!hasNoLeadingOrTrailingSpecialChars) {
    return false;
  }

  const secondAtSymbolCheck = candidateEmailString.indexOf('@', atSymbolIndex + 1);
  const multipleAtSymbolsPresent = secondAtSymbolCheck !== -1;

  if (multipleAtSymbolsPresent) {
    return false;
  }

  return true;
}

