function calculateEuclideanDistance(firstPoint, secondPoint) {
  const xCoordinateDifference = firstPoint.x - secondPoint.x;
  const yCoordinateDifference = firstPoint.y - secondPoint.y;
  const squaredXDifference = xCoordinateDifference * xCoordinateDifference;
  const squaredYDifference = yCoordinateDifference * yCoordinateDifference;
  const sumOfSquares = squaredXDifference + squaredYDifference;
  const finalCalculatedDistance = Math.sqrt(sumOfSquares);
  return finalCalculatedDistance;
}

function computePointSeparation(initialPoint, targetPoint) {
  const dxValue = initialPoint.x - targetPoint.x;
  const dyValue = initialPoint.y - targetPoint.y;
  const sumOfSquaredComponents = dxValue * dxValue + dyValue * dyValue;
  const geometricSpan = Math.sqrt(sumOfSquaredComponents);
  return geometricSpan;
}

function determineSpatialSeparation(pointA, pointB) {
  const horizontalDisplacement = pointA.x - pointB.x;
  const verticalDisplacement = pointA.y - pointB.y;
  const squaredHorizontal = horizontalDisplacement * horizontalDisplacement;
  const squaredVertical = verticalDisplacement * verticalDisplacement;
  const totalSquareSum = squaredHorizontal + squaredVertical;
  const finalMetricValue = Math.sqrt(totalSquareSum);
  return finalMetricValue;
}

