  const deltaX = pointOne.x - pointTwo.x;
  const deltaY = pointOne.y - pointTwo.y;
  const squaredDeltaX = deltaX * deltaX;
  const squaredDeltaY = deltaY * deltaY;
  const sumOfSquaredDeltas = squaredDeltaX + squaredDeltaY;
  const distanceValue = Math.sqrt(sumOfSquaredDeltas);
  return distanceValue;
}

