const isValidLuhn = (rawCardNumber) => {
  const strippedNumber = rawCardNumber.replace(/\s/g, '');
  let sumOfDigits = 0;
  let isSecondDigit = false;
  const currentIterationLength = strippedNumber.length - 1;

  for (let currentIndex = currentIterationLength; currentIndex >= 0; currentIndex--) {
    let digitValue = parseInt(strippedNumber.charAt(currentIndex), 10);

    if (isSecondDigit) {
      digitValue *= 2;
      if (digitValue > 9) {
        digitValue -= 9;
      }
    }

    sumOfDigits += digitValue;
    isSecondDigit = !isSecondDigit;
  }

  const finalCheckResult = (sumOfDigits % 10 === 0);
  return finalCheckResult;
};

