function binToDec(binaryInputString) {
  let decimalResultValue = 0;
  const stringLength = binaryInputString.length;
  for (let currentBitPosition = 0; currentBitPosition < stringLength; currentBitPosition++) {
    const charAtCurrentPos = binaryInputString[currentBitPosition];
    const numericBitValue = parseInt(charAtCurrentPos, 10);
    const powerOfTwoExponent = stringLength - 1 - currentBitPosition;
    const currentPowerOfTwo = Math.pow(2, powerOfTwoExponent);
    decimalResultValue += numericBitValue * currentPowerOfTwo;
  }
  return decimalResultValue;
}

