  let uniqueCharacters = '';
  const seenCharactersSet = new Set();

  for (let characterOfCurrentString of inputStringValue) {
    const isNewCharacter = !seenCharactersSet.has(characterOfCurrentString);
    if (isNewCharacter) {
      uniqueCharacters += characterOfCurrentString;
      seenCharactersSet.add(characterOfCurrentString);
    }
  }

  return uniqueCharacters;
}

const exampleOneInput = 'hello world';
const exampleOneResult = getUniqueChars(exampleOneInput);
const anotherStringInput = 'aabbcc';
const anotherStringResult = getUniqueChars(anotherStringInput);
const yetAnotherString = 'programmingisfun';
const yetAnotherStringResult = getUniqueChars(yetAnotherString);
const myFinalTestString = 'banana';
const myFinalTestResult = getUniqueChars(myFinalTestString);

