function levenshteinDistance(firstStringInput, secondStringInput) {
  const s1Len = firstStringInput.length;
  const s2Len = secondStringInput.length;

  let currentDistances = Array(s2Len + 1).fill(0).map((val, index) => index);

  for (let i = 1; i <= s1Len; i++) {
    let previousRowValue = currentDistances[0];
    currentDistances[0] = i;
    for (let j = 1; j <= s2Len; j++) {
      const temporaryValue = currentDistances[j];
      const costOfSubstitution = (firstStringInput[i - 1] === secondStringInput[j - 1]) ? 0 : 1;
      currentDistances[j] = Math.min(
        currentDistances[j - 1] + 1,        // Deletion
        currentDistances[j] + 1,            // Insertion
        previousRowValue + costOfSubstitution // Substitution
      );
      previousRowValue = temporaryValue;
    }
  }

  const finalCalculatedDistance = currentDistances[s2Len];
  return finalCalculatedDistance;
}

