function rgbToHex(redValue, greenValue, blueValue) {
  const componentToHex = (colorComponent) => {
    let hexRepresentation = colorComponent.toString(16);
    return hexRepresentation.length === 1 ? '0' + hexRepresentation : hexRepresentation;
  };

  let hexRed = componentToHex(redValue);
  let hexGreen = componentToHex(greenValue);
  let hexBlue = componentToHex(blueValue);

  let finalHexString = `#${hexRed.toUpperCase()}${hexGreen.toUpperCase()}${hexBlue.toUpperCase()}`;
  return finalHexString;
}

