function daysBetween(firstDateString, secondDateString) {
  const oneDayMilliseconds = 1000 * 60 * 60 * 24;
  const initialDateObject = new Date(firstDateString);
  const finalDateObject = new Date(secondDateString);

  const timeDifferenceMilliseconds = Math.abs(finalDateObject.getTime() - initialDateObject.getTime());
  const calculatedDayCount = Math.floor(timeDifferenceMilliseconds / oneDayMilliseconds);

  return calculatedDayCount;
}

