function days_between(first_date_string, second_date_string) {
  const one_day_milliseconds = 1000 * 60 * 60 * 24;
  const initial_date_object = new Date(first_date_string);
  const final_date_object = new Date(second_date_string);

  const time_difference_milliseconds = Math.abs(final_date_object.getTime() - initial_date_object.getTime());
  const calculated_day_count = Math.floor(time_difference_milliseconds / one_day_milliseconds);

  return calculated_day_count;
}

