function shuffleDeck(originalCardDeck) {
  let currentDeckLength = originalCardDeck.length;
  let newShuffledDeck = [...originalCardDeck];
  let temporaryCardStorage;
  let randomIndexPosition;

  while (currentDeckLength > 0) {
    randomIndexPosition = Math.floor(Math.random() * currentDeckLength);
    currentDeckLength--;

    temporaryCardStorage = newShuffledDeck[currentDeckLength];
    newShuffledDeck[currentDeckLength] = newShuffledDeck[randomIndexPosition];
    newShuffledDeck[randomIndexPosition] = temporaryCardStorage;
  }

  return newShuffledDeck;
}

function generateStandardDeck() {
  const cardSuits = ['H', 'D', 'C', 'S'];
  const cardRanks = ['2', '3', '4', '5', '6', '7', '8', '9', 'T', 'J', 'Q', 'K', 'A'];
  const newFullDeck = [];

  for (const eachSuit of cardSuits) {
    for (const eachRank of cardRanks) {
      newFullDeck.push(eachRank + eachSuit);
    }
  }
  return newFullDeck;
}

const fullCardDeck = generateStandardDeck();
const trulyRandomizedDeck = shuffleDeck(fullCardDeck);

const smallTestDeck = ['AH', 'KH', 'QH'];
const smallerShuffledDeck = shuffleDeck(smallTestDeck);

