function countVowelsAndConsonants(inputStringValue) {
  let totalVowelCount = 0;
  let totalConsonantCount = 0;
  const allVowels = 'aeiou';
  const characterArray = inputStringValue.toLowerCase().split('');

  for (const singleChar of characterArray) {
    if (singleChar >= 'a' && singleChar <= 'z') {
      if (allVowels.includes(singleChar)) {
        totalVowelCount++;
      } else {
        totalConsonantCount++;
      }
    }
  }

  const finalResultObject = {
    vowels: totalVowelCount,
    consonants: totalConsonantCount,
  };
  return finalResultObject;
}

